int AnswerQuestion(string question) {
    string answer = "";
    // Arabic countries
    string[] countries = {"Egypt", "Saudi Arabia", "United Arab Emirates", "Algeria", "Iraq", "Jordan", "Kuwait", "Lebanon", "Libya", "Morocco", "Oman", "Qatar", "Syria", "Tunisia", "Yemen"};
    // Verse and Hadiths
    // Verses
    QuranVerse[] verses = {
        new QuranVerse("Surat Al-Baqarah", 224, "And they ask you about menstruation. Say, 'It is harm, so keep away from women during menstruation. And do not approach them until they are pure. And when they are pure, then go to them as Allah has instructed you.'"),
        new QuranVerse("Surat Al-Nisa", 127, "And they ask you about men, say, 'Allah makes whatever He wills.'"),
        new QuranVerse("Surat Al-Ahzab", 51, "And when you ask them for something of them, ask them from behind a screen. That is purer for your hearts and their hearts. And it is not [right] for you to distress them, and Allah is ever Forgiving and Merciful."),
    };
    // Hadiths
    Hadith[] hadiths = {
        new Hadith("Bukhari", 46, "Narrated 'Aisha: The Prophet used to perform ablution with water and then pour it over his head and wash his hands and feet, and then pray while facing the Qibla without using the Miswak, and when he finished the prayer, he would wipe his hands over the tips of the grass (in the mosque)."),
        new Hadith("Muslim", 191, "Narrated 'Umar bin Al-Khattab: When the Verse: 'They ask you about menstruation.' was revealed, the women used to come to the Prophet and ask him about it. The Prophet would order them to use miswak, to use it at the time of menses, and to clean their private parts with stones.")
    };

    // Check if the question is about a woman and a country
    if (question.Contains("woman") && countries.Contains(question.Split(' ')[2])) {
        // Find the most relevant verse or hadith
        QuranVerse mostRelevantVerse = verses[0];
        Hadith mostRelevantHadith = hadiths[0];
        foreach (QuranVerse verse in verses) {
            if (question.Contains(verse.VerseText)) {
                if (verse.VerseText.Length < mostRelevantVerse.VerseText.Length) {
                    mostRelevantVerse = verse;
                }
            }
        }
        foreach (Hadith hadith in hadiths) {
            if (question.Contains(hadith.HadithText)) {
                if (hadith.HadithText.Length < mostRelevantHadith.HadithText.Length) {
                    mostRelevantHadith = hadith;
                }
            }
        }

        // Answer the question with the most relevant verse or hadith
        answer += "The most relevant verse is: " + mostRelevantVerse.VerseText + " (" + mostRelevantVerse.SurahName + ", " + mostRelevantVerse.VerseNumber + ").\n";
        answer += "The most relevant hadith is: " + mostRelevantHadith.HadithText + " (" + mostRelevantHadith.Source + ", " + mostRelevantHadith.Number + ").\n";
    }

    return answer;
}

class QuranVerse {
    public string SurahName { get; set; }
    public int VerseNumber { get; set; }
    public string VerseText { get; set; }
}

class Hadith {
    public string Source { get; set; }
    public int Number { get; set; }
    public string HadithText { get; set; }
}

